// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        vm.deal(address(c), amount);

        // Fund the contract
        (bool success, ) = address(c).call{value: amount}("");

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Try to withdraw as caller
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector, recipient));

        // The general rule: if caller is owner, call succeeds and contract balance becomes 0; otherwise reverts
        if (caller == address(this)) {
            assertTrue(ok, "Owner should succeed");
            assertEq(address(c).balance, 0, "Contract should be empty after owner withdraw");
        } else {
            assertTrue(!ok, "Non-owner should revert");
        }
    }
}
